use clap::{Parser, ValueEnum};
use csv::ReaderBuilder;
use std::fmt;
use std::fs::File;
use std::io::{self, IsTerminal, Read, Write};
use std::process::{Command, Stdio};
use terminal_size::{terminal_size, Height};
use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

#[derive(Parser, Debug)]
#[command(
    name = "csview",
    bin_name = "executable",
    version = "1.3.4",
    about = "A high performance csv viewer with cjk/emoji support."
)]
struct Opts {
    #[arg(short = 'H', long = "no-headers", help = "Specify that the input has no header row")]
    no_headers: bool,

    #[arg(short, long, help = "Prepend a column of line numbers to the table")]
    number: bool,

    #[arg(
        short,
        long,
        conflicts_with = "delimiter",
        help = "Use '\\t' as delimiter for tsv"
    )]
    tsv: bool,

    #[arg(
        short,
        long,
        default_value = ",",
        conflicts_with = "tsv",
        help = "Specify the field delimiter"
    )]
    delimiter: char,

    #[arg(
        short,
        long,
        value_enum,
        default_value_t = StyleChoice::Sharp,
        help = "Specify the border style"
    )]
    style: StyleChoice,

    #[arg(
        short,
        long,
        default_value_t = 1usize,
        help = "Specify padding for table cell"
    )]
    padding: usize,

    #[arg(
        short,
        long,
        default_value_t = 0usize,
        help = "Specify global indent for table"
    )]
    indent: usize,

    #[arg(
        long,
        default_value_t = 1000usize,
        help = "Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit"
    )]
    sniff: usize,

    #[arg(
        long = "header-align",
        value_enum,
        default_value_t = AlignChoice::Center,
        help = "Specify the alignment of the table header"
    )]
    header_align: AlignChoice,

    #[arg(
        long = "body-align",
        value_enum,
        default_value_t = AlignChoice::Left,
        help = "Specify the alignment of the table body"
    )]
    body_align: AlignChoice,

    #[arg(short = 'P', long = "disable-pager", help = "Disable pager")]
    disable_pager: bool,

    #[arg(value_name = "FILE", help = "File to view")]
    file: Option<String>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
enum StyleChoice {
    None,
    Ascii,
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
enum AlignChoice {
    Left,
    Center,
    Right,
}

#[derive(Debug)]
enum AppError {
    Io(io::Error),
    Csv(csv::Error),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
