#[derive(Debug)]
struct TableData {
    render_header: bool,
    header: Vec<String>,
    rows: Vec<Vec<String>>,
    widths: Vec<usize>,
}

#[derive(Clone, Copy)]
struct BorderStyle<'a> {
    top_left: &'a str,
    top_mid: &'a str,
    top_right: &'a str,
    top_fill: &'a str,
    mid_left: &'a str,
    mid_mid: &'a str,
    mid_right: &'a str,
    mid_fill: &'a str,
    row_left: &'a str,
    row_mid: &'a str,
    row_right: &'a str,
    bottom_left: &'a str,
    bottom_mid: &'a str,
    bottom_right: &'a str,
    bottom_fill: &'a str,
}

fn main() {
    let opts = Opts::parse();
    if let Err(err) = run(opts) {
        eprintln!("csview: {err}");
        std::process::exit(1);
    }
}

fn run(opts: Opts) -> Result<(), AppError> {
    let table = load_table(&opts)?;
    let output = render_table(&table, &opts);
    emit_output(&output, opts.disable_pager)?;
    Ok(())
}

fn load_table(opts: &Opts) -> Result<TableData, AppError> {
    let reader: Box<dyn Read> = match &opts.file {
        Some(path) => Box::new(File::open(path)?),
        None => Box::new(io::stdin()),
    };

    let delimiter = if opts.tsv {
        b'\t'
    } else {
        opts.delimiter as u32 as u8
    };

    let mut csv = ReaderBuilder::new()
        .delimiter(delimiter)
        .has_headers(!opts.no_headers)
        .from_reader(reader);

    let raw_header = if opts.no_headers {
        None
    } else {
        Some(
            csv.headers()?
                .iter()
                .map(str::to_owned)
                .collect::<Vec<String>>(),
        )
    };

    let mut rows = Vec::new();
    for record in csv.records() {
        let record = record?;
        rows.push(record.iter().map(str::to_owned).collect::<Vec<String>>());
    }

    let mut header = raw_header.unwrap_or_default();
    if opts.number {
        for (index, row) in rows.iter_mut().enumerate() {
            row.insert(0, (index + 1).to_string());
        }
        if !opts.no_headers {
            header.insert(0, "#".to_string());
        }
    }

    let render_header = !opts.no_headers;
    let column_count = if render_header {
        header.len()
    } else if let Some(first) = rows.first() {
        first.len()
    } else if opts.number {
        1
    } else {
        0
    };

    let mut widths = vec![0; column_count];
    if render_header {
        update_widths(&mut widths, &header);
    } else if opts.number && !widths.is_empty() {
        widths[0] = display_width("#");
    }

    let sniff_rows = if opts.sniff == 0 {
        rows.len()
    } else {
        opts.sniff.min(rows.len())
    };
    for row in rows.iter().take(sniff_rows) {
        update_widths(&mut widths, row);
    }

    Ok(TableData {
        render_header,
        header,
        rows,
        widths,
    })
}

fn update_widths(widths: &mut [usize], row: &[String]) {
    for (width, cell) in widths.iter_mut().zip(row) {
        *width = (*width).max(display_width(cell));
    }
}

fn render_table(table: &TableData, opts: &Opts) -> String {
    let lines = match opts.style {
        StyleChoice::None => render_plain(table, opts),
        StyleChoice::Ascii2 => render_ascii2(table, opts),
        StyleChoice::Markdown => render_markdown(table, opts),
        StyleChoice::Ascii => render_boxed(table, opts, box_style_ascii(), false),
        StyleChoice::Sharp => render_boxed(table, opts, box_style_sharp(), false),
        StyleChoice::Rounded => render_boxed(table, opts, box_style_rounded(), false),
        StyleChoice::Reinforced => render_boxed(table, opts, box_style_reinforced(), false),
        StyleChoice::Grid => render_boxed(table, opts, box_style_sharp(), true),
    };

    if lines.is_empty() {
        return String::new();
    }

    let prefix = " ".repeat(opts.indent);
    let mut output = String::new();
    for line in lines {
        output.push_str(&prefix);
        output.push_str(&line);
        output.push('\n');
    }
    output
}

fn render_plain(table: &TableData, opts: &Opts) -> Vec<String> {
    if table.widths.is_empty() {
        return Vec::new();
    }

    let mut lines = Vec::new();
    if table.render_header {
        lines.push(render_row_plain(
            &table.header,
            &table.widths,
            opts.header_align,
            opts.padding,
        ));
    }
    for row in &table.rows {
        lines.push(render_row_plain(row, &table.widths, opts.body_align, opts.padding));
    }
    lines
}

fn render_ascii2(table: &TableData, opts: &Opts) -> Vec<String> {
    if table.widths.is_empty() {
        return if table.render_header {
            vec!["  ".to_string()]
        } else {
            Vec::new()
        };
    }

    let mut lines = Vec::new();
    if table.render_header {
        lines.push(render_row_joined(
            &table.header,
            &table.widths,
            opts.header_align,
            opts.padding,
            "",
            "|",
            "",
        ));
        if !table.rows.is_empty() {
            lines.push(render_border(" ", "+", " ", "-", &table.widths, opts.padding));
        }
    }
    for row in &table.rows {
        lines.push(render_row_joined(
            row,
            &table.widths,
            opts.body_align,
            opts.padding,
            "",
            "|",
            "",
        ));
    }
    lines
}

fn render_markdown(table: &TableData, opts: &Opts) -> Vec<String> {
    if table.widths.is_empty() {
        return if table.render_header {
            vec!["||".to_string()]
        } else {
            Vec::new()
        };
    }

    let mut lines = Vec::new();
    if table.render_header {
        lines.push(render_row_joined(
            &table.header,
            &table.widths,
            opts.header_align,
            opts.padding,
            "|",
            "|",
            "|",
        ));
        if !table.rows.is_empty() {
            lines.push(render_border("|", "|", "|", "-", &table.widths, opts.padding));
        }
    }
    for row in &table.rows {
        lines.push(render_row_joined(
            row,
            &table.widths,
            opts.body_align,
            opts.padding,
            "|",
            "|",
            "|",
        ));
    }
    lines
}

fn render_boxed(
    table: &TableData,
    opts: &Opts,
    style: BorderStyle<'_>,
    grid: bool,
) -> Vec<String> {
    if table.widths.is_empty() {
        let mut lines = Vec::new();
        lines.push(format!("{}{}", style.top_left, style.top_right));
        if table.render_header {
            lines.push(format!("{}{}", style.row_left, style.row_right));
        }
        lines.push(format!("{}{}", style.bottom_left, style.bottom_right));
        return lines;
    }

    let mut lines = Vec::new();
    lines.push(render_border(
        style.top_left,
        style.top_mid,
        style.top_right,
        style.top_fill,
        &table.widths,
        opts.padding,
    ));

    if table.render_header {
        lines.push(render_row_joined(
            &table.header,
            &table.widths,
            opts.header_align,
            opts.padding,
            style.row_left,
            style.row_mid,
            style.row_right,
        ));
        if !table.rows.is_empty() {
            lines.push(render_border(
                style.mid_left,
                style.mid_mid,
                style.mid_right,
                style.mid_fill,
                &table.widths,
                opts.padding,
            ));
        }
    }

    for (index, row) in table.rows.iter().enumerate() {
        lines.push(render_row_joined(
            row,
            &table.widths,
            opts.body_align,
            opts.padding,
            style.row_left,
            style.row_mid,
            style.row_right,
        ));
        if grid && index + 1 < table.rows.len() {
            lines.push(render_border(
                style.mid_left,
                style.mid_mid,
                style.mid_right,
                style.mid_fill,
                &table.widths,
                opts.padding,
            ));
        }
    }

    lines.push(render_border(
        style.bottom_left,
        style.bottom_mid,
        style.bottom_right,
        style.bottom_fill,
        &table.widths,
        opts.padding,
    ));

    lines
}

fn render_row_plain(
    row: &[String],
    widths: &[usize],
    align: AlignChoice,
    padding: usize,
) -> String {
    row.iter()
        .zip(widths)
        .map(|(cell, width)| render_cell(cell, *width, align, padding))
        .collect::<String>()
}

fn render_row_joined(
    row: &[String],
    widths: &[usize],
    align: AlignChoice,
    padding: usize,
    left: &str,
    mid: &str,
    right: &str,
) -> String {
    let rendered = row
        .iter()
        .zip(widths)
        .map(|(cell, width)| render_cell(cell, *width, align, padding))
        .collect::<Vec<String>>();
    format!("{left}{}{right}", rendered.join(mid))
}

fn render_cell(cell: &str, width: usize, align: AlignChoice, padding: usize) -> String {
    let content = truncate_to_width(cell, width);
    let content_width = display_width(&content);
    let pad = width.saturating_sub(content_width);
    let (left_fill, right_fill) = match align {
        AlignChoice::Left => (0, pad),
        AlignChoice::Center => (pad / 2, pad - (pad / 2)),
        AlignChoice::Right => (pad, 0),
    };

    let mut out = String::new();
    out.push_str(&" ".repeat(padding));
    out.push_str(&" ".repeat(left_fill));
    out.push_str(&content);
    out.push_str(&" ".repeat(right_fill));
    out.push_str(&" ".repeat(padding));
    out
}

fn render_border(
    left: &str,
    mid: &str,
    right: &str,
    fill: &str,
    widths: &[usize],
    padding: usize,
) -> String {
    let cells = widths
        .iter()
        .map(|width| fill.repeat(width + (padding * 2)))
        .collect::<Vec<String>>();
    format!("{left}{}{right}", cells.join(mid))
}

fn display_width(text: &str) -> usize {
    text.graphemes(true).map(grapheme_width).sum()
}

fn grapheme_width(grapheme: &str) -> usize {
    match grapheme {
        "\n" | "\r" | "\r\n" => 1,
        _ => UnicodeWidthStr::width(grapheme),
    }
}

fn truncate_to_width(text: &str, max_width: usize) -> String {
    if max_width == 0 {
        return String::new();
    }

    let mut width = 0;
    let mut out = String::new();
    for grapheme in text.graphemes(true) {
        let g_width = grapheme_width(grapheme);
        if g_width > 0 && width + g_width > max_width {
            break;
        }
        width += g_width;
        out.push_str(grapheme);
    }
    out
}

fn emit_output(output: &str, disable_pager: bool) -> Result<(), AppError> {
    if output.is_empty() {
        return Ok(());
    }

    if !disable_pager && io::stdout().is_terminal() && should_page(output) {
        if page_with_more(output).is_ok() {
            return Ok(());
        }
    }

    write_direct(output)
}

fn should_page(output: &str) -> bool {
    let line_count = output.lines().count();
    let height = terminal_size()
        .map(|(_, Height(height))| height as usize)
        .unwrap_or(24);
    line_count >= height
}

fn page_with_more(output: &str) -> io::Result<()> {
    let mut child = Command::new("more")
        .stdin(Stdio::piped())
        .spawn()?;

    if let Some(mut stdin) = child.stdin.take() {
        match stdin.write_all(output.as_bytes()) {
            Ok(()) => {}
            Err(err) if err.kind() == io::ErrorKind::BrokenPipe => return Ok(()),
            Err(err) => return Err(err),
        }
    }

    match child.wait() {
        Ok(_) => Ok(()),
        Err(err) if err.kind() == io::ErrorKind::BrokenPipe => Ok(()),
        Err(err) => Err(err),
    }
}

fn write_direct(output: &str) -> Result<(), AppError> {
    let mut stdout = io::stdout().lock();
    match stdout.write_all(output.as_bytes()) {
        Ok(()) => Ok(()),
        Err(err) if err.kind() == io::ErrorKind::BrokenPipe => Ok(()),
        Err(err) => Err(err.into()),
    }
}

fn box_style_ascii() -> BorderStyle<'static> {
    BorderStyle {
        top_left: "+",
        top_mid: "+",
        top_right: "+",
        top_fill: "-",
        mid_left: "+",
        mid_mid: "+",
        mid_right: "+",
        mid_fill: "-",
        row_left: "|",
        row_mid: "|",
        row_right: "|",
        bottom_left: "+",
        bottom_mid: "+",
        bottom_right: "+",
        bottom_fill: "-",
    }
}

fn box_style_sharp() -> BorderStyle<'static> {
    BorderStyle {
        top_left: "┌",
        top_mid: "┬",
        top_right: "┐",
        top_fill: "─",
        mid_left: "├",
        mid_mid: "┼",
        mid_right: "┤",
        mid_fill: "─",
        row_left: "│",
        row_mid: "│",
        row_right: "│",
        bottom_left: "└",
        bottom_mid: "┴",
        bottom_right: "┘",
        bottom_fill: "─",
    }
}

fn box_style_rounded() -> BorderStyle<'static> {
    BorderStyle {
        top_left: "╭",
        top_mid: "┬",
        top_right: "╮",
        top_fill: "─",
        mid_left: "├",
        mid_mid: "┼",
        mid_right: "┤",
        mid_fill: "─",
        row_left: "│",
        row_mid: "│",
        row_right: "│",
        bottom_left: "╰",
        bottom_mid: "┴",
        bottom_right: "╯",
        bottom_fill: "─",
    }
}

fn box_style_reinforced() -> BorderStyle<'static> {
    BorderStyle {
        top_left: "┏",
        top_mid: "┬",
        top_right: "┓",
        top_fill: "─",
        mid_left: "├",
        mid_mid: "┼",
        mid_right: "┤",
        mid_fill: "─",
        row_left: "│",
        row_mid: "│",
        row_right: "│",
        bottom_left: "┗",
        bottom_mid: "┴",
        bottom_right: "┛",
        bottom_fill: "─",
    }
}

