}

fn load_table(opts: &Opts) -> Result<TableData, AppError> {
    let reader: Box<dyn Read> = match &opts.file {
        Some(path) => Box::new(File::open(path)?),
        None => Box::new(io::stdin()),
    };

    let delimiter = if opts.tsv {
        b'\t'
    } else {
        opts.delimiter as u32 as u8
    };

    let mut csv = ReaderBuilder::new()
        .delimiter(delimiter)
        .has_headers(!opts.no_headers)
        .from_reader(reader);

    let raw_header = if opts.no_headers {
        None
    } else {
        Some(
            csv.headers()?
                .iter()
                .map(str::to_owned)
                .collect::<Vec<String>>(),
        )
    };

    let mut rows = Vec::new();
    for record in csv.records() {
        let record = record?;
        rows.push(record.iter().map(str::to_owned).collect::<Vec<String>>());
    }

    let mut header = raw_header.unwrap_or_default();
    if opts.number {
        for (index, row) in rows.iter_mut().enumerate() {
            row.insert(0, (index + 1).to_string());
        }
        if !opts.no_headers {
            header.insert(0, "#".to_string());
        }
    }

    let render_header = !opts.no_headers;
    let column_count = if render_header {
        header.len()
    } else if let Some(first) = rows.first() {
        first.len()
    } else if opts.number {
        1
    } else {
        0
    };

    let mut widths = vec![0; column_count];
    if render_header {
        update_widths(&mut widths, &header);
    } else if opts.number && !widths.is_empty() {
        widths[0] = display_width("#");
    }

    let sniff_rows = if opts.sniff == 0 {
        rows.len()
    } else {
        opts.sniff.min(rows.len())
    };
    for row in rows.iter().take(sniff_rows) {
        update_widths(&mut widths, row);
    }

    Ok(TableData {
        render_header,
        header,
        rows,
        widths,
    })
}

fn update_widths(widths: &mut [usize], row: &[String]) {
    for (width, cell) in widths.iter_mut().zip(row) {
        *width = (*width).max(display_width(cell));
    }
}

fn render_table(table: &TableData, opts: &Opts) -> String {
    let lines = match opts.style {
        StyleChoice::None => render_plain(table, opts),
        StyleChoice::Ascii2 => render_ascii2(table, opts),
        StyleChoice::Markdown => render_markdown(table, opts),
        StyleChoice::Ascii => render_boxed(table, opts, box_style_ascii(), false),
        StyleChoice::Sharp => render_boxed(table, opts, box_style_sharp(), false),
        StyleChoice::Rounded => render_boxed(table, opts, box_style_rounded(), false),
        StyleChoice::Reinforced => render_boxed(table, opts, box_style_reinforced(), false),
        StyleChoice::Grid => render_boxed(table, opts, box_style_sharp(), true),
    };

    if lines.is_empty() {
        return String::new();
    }

    let prefix = " ".repeat(opts.indent);
    let mut output = String::new();
    for line in lines {
        output.push_str(&prefix);
        output.push_str(&line);
        output.push('\n');
    }
    output
}

fn render_plain(table: &TableData, opts: &Opts) -> Vec<String> {
    if table.widths.is_empty() {
        return Vec::new();
