fn render_boxed(
    table: &TableData,
    opts: &Opts,
    style: BorderStyle<'_>,
    grid: bool,
) -> Vec<String> {
    if table.widths.is_empty() {
        let mut lines = Vec::new();
        lines.push(format!("{}{}", style.top_left, style.top_right));
        if table.render_header {
            lines.push(format!("{}{}", style.row_left, style.row_right));
        }
        lines.push(format!("{}{}", style.bottom_left, style.bottom_right));
        return lines;
    }

    let mut lines = Vec::new();
    lines.push(render_border(
        style.top_left,
        style.top_mid,
        style.top_right,
        style.top_fill,
        &table.widths,
        opts.padding,
    ));

    if table.render_header {
        lines.push(render_row_joined(
            &table.header,
            &table.widths,
            opts.header_align,
            opts.padding,
            style.row_left,
            style.row_mid,
            style.row_right,
        ));
        if !table.rows.is_empty() {
            lines.push(render_border(
                style.mid_left,
                style.mid_mid,
                style.mid_right,
                style.mid_fill,
                &table.widths,
                opts.padding,
            ));
        }
    }

    for (index, row) in table.rows.iter().enumerate() {
        lines.push(render_row_joined(
            row,
            &table.widths,
            opts.body_align,
            opts.padding,
            style.row_left,
            style.row_mid,
            style.row_right,
        ));
        if grid && index + 1 < table.rows.len() {
            lines.push(render_border(
                style.mid_left,
                style.mid_mid,
                style.mid_right,
                style.mid_fill,
                &table.widths,
                opts.padding,
            ));
        }
