use std::env;
use std::fmt;
use std::fs::File;
use std::io::{self, IsTerminal, Read, Write};
use std::process::{Command, Stdio};

const HELP_TEXT: &str = "\
A high performance csv viewer with cjk/emoji support.

Usage: executable [OPTIONS] [FILE]

Arguments:
  [FILE]
          File to view

Options:
  -H, --no-headers
          Specify that the input has no header row
  -n, --number
          Prepend a column of line numbers to the table
  -t, --tsv
          Use '\\t' as delimiter for tsv
  -d, --delimiter <DELIMITER>
          Specify the field delimiter [default: ,]
  -s, --style <STYLE>
          Specify the border style [default: sharp] [possible values: none, ascii, ascii2, sharp,
          rounded, reinforced, markdown, grid]
  -p, --padding <PADDING>
          Specify padding for table cell [default: 1]
  -i, --indent <INDENT>
          Specify global indent for table [default: 0]
      --sniff <LIMIT>
          Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit
          [default: 1000]
      --header-align <HEADER_ALIGN>
          Specify the alignment of the table header [default: center] [possible values: left,
          center, right]
      --body-align <BODY_ALIGN>
          Specify the alignment of the table body [default: left] [possible values: left, center,
          right]
  -P, --disable-pager
          Disable pager
  -h, --help
          Print help
  -V, --version
          Print version
";

const VERSION_TEXT: &str = "csview 1.3.4\n";
const USAGE_GENERIC: &str = "Usage: executable [OPTIONS] [FILE]";

fn main() {
    match parse_args() {
        Ok(ParseOutcome::Help) => {
            print!("{HELP_TEXT}");
        }
        Ok(ParseOutcome::Version) => {
            print!("{VERSION_TEXT}");
        }
        Ok(ParseOutcome::Run(opts)) => {
            if let Err(err) = run(&opts) {
                eprintln!("csview: {err}");
                std::process::exit(1);
            }
        }
        Err(err) => {
            eprint!("{}", err.render());
            std::process::exit(2);
        }
    }
}

fn run(opts: &Opts) -> Result<(), AppError> {
    let table = load_table(opts)?;
    let output = render_table(&table, opts);
    emit_output(&output, opts.disable_pager)?;
    Ok(())
}

#[derive(Clone, Debug)]
struct Opts {
    no_headers: bool,
    number: bool,
    tsv: bool,
    delimiter: char,
    style: StyleChoice,
    padding: usize,
    indent: usize,
    sniff: usize,
    header_align: AlignChoice,
    body_align: AlignChoice,
    disable_pager: bool,
    file: Option<String>,
}

impl Default for Opts {
    fn default() -> Self {
        Self {
            no_headers: false,
            number: false,
            tsv: false,
            delimiter: ',',
            style: StyleChoice::Sharp,
            padding: 1,
            indent: 0,
            sniff: 1000,
            header_align: AlignChoice::Center,
            body_align: AlignChoice::Left,
            disable_pager: false,
            file: None,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum StyleChoice {
    None,
    Ascii,
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

impl StyleChoice {
    fn parse(raw: &str) -> Option<Self> {
        match raw {
            "none" => Some(Self::None),
            "ascii" => Some(Self::Ascii),
            "ascii2" => Some(Self::Ascii2),
            "sharp" => Some(Self::Sharp),
            "rounded" => Some(Self::Rounded),
            "reinforced" => Some(Self::Reinforced),
            "markdown" => Some(Self::Markdown),
            "grid" => Some(Self::Grid),
            _ => None,
        }
    }

    fn possible_values() -> &'static str {
        "none, ascii, ascii2, sharp, rounded, reinforced, markdown, grid"
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AlignChoice {
    Left,
    Center,
    Right,
}

impl AlignChoice {
    fn parse(raw: &str) -> Option<Self> {
        match raw {
            "left" => Some(Self::Left),
            "center" => Some(Self::Center),
            "right" => Some(Self::Right),
            _ => None,
        }
    }

    fn possible_values() -> &'static str {
        "left, center, right"
    }
}

enum ParseOutcome {
    Help,
    Version,
    Run(Opts),
}

enum CliError {
    UnexpectedArgument {
        arg: String,
        suggestion: Option<&'static str>,
        usage: &'static str,
    },
    MissingValue {
        flag: &'static str,
    },
    InvalidValue {
        raw: String,
        flag: &'static str,
        detail: String,
    },
    InvalidEnum {
        raw: String,
        flag: &'static str,
        values: &'static str,
    },
    Conflict {
        earlier: &'static str,
        current: &'static str,
        usage: &'static str,
    },
}

impl CliError {
    fn render(&self) -> String {
        match self {
            Self::UnexpectedArgument {
                arg,
                suggestion,
                usage,
            } => {
                let mut out = format!("error: unexpected argument '{arg}' found\n");
                if let Some(suggestion) = suggestion {
                    out.push_str(&format!("\n  tip: a similar argument exists: '{suggestion}'\n"));
                } else if arg.starts_with('-') {
                    out.push_str(&format!("\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n"));
                }
                out.push_str(&format!("\n{usage}\n\nFor more information, try '--help'.\n"));
                out
            }
            Self::MissingValue { flag } => format!(
                "error: a value is required for '{flag}' but none was supplied\n\nFor more information, try '--help'.\n"
            ),
            Self::InvalidValue { raw, flag, detail } => format!(
                "error: invalid value '{raw}' for '{flag}': {detail}\n\nFor more information, try '--help'.\n"
            ),
            Self::InvalidEnum { raw, flag, values } => format!(
                "error: invalid value '{raw}' for '{flag}' [possible values: {values}]\n\nFor more information, try '--help'.\n"
            ),
            Self::Conflict {
                earlier,
                current,
                usage,
            } => format!(
                "error: the argument '{earlier}' cannot be used with '{current}'\n\n{usage}\n\nFor more information, try '--help'.\n"
            ),
        }
    }
}

fn parse_args() -> Result<ParseOutcome, CliError> {
    let args = env::args().skip(1).collect::<Vec<String>>();
    let mut opts = Opts::default();
    let mut stop_options = false;
    let mut tsv_seen = false;
    let mut delimiter_seen = false;
    let mut index = 0usize;

    while index < args.len() {
        let arg = &args[index];

        if !stop_options && (arg == "-h" || arg == "--help") {
            return Ok(ParseOutcome::Help);
        }
        if !stop_options && (arg == "-V" || arg == "--version") {
            return Ok(ParseOutcome::Version);
        }

        if !stop_options && arg == "--" {
            stop_options = true;
            index += 1;
            continue;
        }

        if !stop_options {
            match arg.as_str() {
                "-H" | "--no-headers" => {
                    opts.no_headers = true;
                    index += 1;
                    continue;
                }
                "-n" | "--number" => {
                    opts.number = true;
                    index += 1;
                    continue;
                }
                "-t" | "--tsv" => {
                    if delimiter_seen {
                        return Err(CliError::Conflict {
                            earlier: "--delimiter <DELIMITER>",
                            current: "--tsv",
                            usage: "Usage: executable --disable-pager --delimiter <DELIMITER> <FILE>",
                        });
                    }
                    opts.tsv = true;
                    tsv_seen = true;
                    index += 1;
                    continue;
                }
                "-P" | "--disable-pager" => {
                    opts.disable_pager = true;
                    index += 1;
                    continue;
                }
                _ => {}
            }

            if let Some(raw) = value_from_arg(&args, &mut index, "-d", "--delimiter")? {
                if tsv_seen {
                    return Err(CliError::Conflict {
                        earlier: "--tsv",
                        current: "--delimiter <DELIMITER>",
                        usage: "Usage: executable --disable-pager --tsv <FILE>",
                    });
                }
                opts.delimiter = parse_char_value(raw, "--delimiter <DELIMITER>")?;
                delimiter_seen = true;
                continue;
            }

            if let Some(raw) = value_from_arg(&args, &mut index, "-s", "--style")? {
                opts.style = StyleChoice::parse(&raw).ok_or_else(|| CliError::InvalidEnum {
                    raw,
                    flag: "--style <STYLE>",
                    values: StyleChoice::possible_values(),
                })?;
                continue;
            }

            if let Some(raw) = value_from_arg(&args, &mut index, "-p", "--padding")? {
                opts.padding = parse_usize_value(raw, "--padding <PADDING>")?;
                continue;
            }

            if let Some(raw) = value_from_arg(&args, &mut index, "-i", "--indent")? {
                opts.indent = parse_usize_value(raw, "--indent <INDENT>")?;
                continue;
            }

            if let Some(raw) = value_from_arg(&args, &mut index, "", "--sniff")? {
                opts.sniff = parse_usize_value(raw, "--sniff <LIMIT>")?;
                continue;
            }

            if let Some(raw) = value_from_arg(&args, &mut index, "", "--header-align")? {
                opts.header_align =
                    AlignChoice::parse(&raw).ok_or_else(|| CliError::InvalidEnum {
                        raw,
                        flag: "--header-align <HEADER_ALIGN>",
                        values: AlignChoice::possible_values(),
                    })?;
                continue;
            }

            if let Some(raw) = value_from_arg(&args, &mut index, "", "--body-align")? {
                opts.body_align = AlignChoice::parse(&raw).ok_or_else(|| CliError::InvalidEnum {
                    raw,
                    flag: "--body-align <BODY_ALIGN>",
                    values: AlignChoice::possible_values(),
                })?;
                continue;
            }

            if arg.starts_with('-') && arg != "-" {
                return Err(CliError::UnexpectedArgument {
                    arg: arg.clone(),
                    suggestion: suggestion_for(arg),
                    usage: USAGE_GENERIC,
                });
            }
        }

        if opts.file.is_none() {
            opts.file = Some(arg.clone());
        } else {
            return Err(CliError::UnexpectedArgument {
                arg: arg.clone(),
                suggestion: None,
                usage: USAGE_GENERIC,
            });
        }
        index += 1;
    }

    Ok(ParseOutcome::Run(opts))
}

fn value_from_arg(
    args: &[String],
    index: &mut usize,
    short: &'static str,
    long: &'static str,
) -> Result<Option<String>, CliError> {
    let arg = &args[*index];

    if !long.is_empty() && arg == long {
        let value_index = *index + 1;
        if value_index >= args.len() {
            return Err(CliError::MissingValue {
                flag: value_flag_name(short, long),
            });
        }
        let value = &args[value_index];
        if value.starts_with('-') && value != "-" {
            return Err(CliError::UnexpectedArgument {
                arg: value.clone(),
                suggestion: suggestion_for(value),
                usage: USAGE_GENERIC,
            });
        }
        *index += 2;
        return Ok(Some(value.clone()));
    }

    if !long.is_empty() {
        let prefix = format!("{long}=");
        if let Some(value) = arg.strip_prefix(&prefix) {
            *index += 1;
            return Ok(Some(value.to_string()));
        }
    }

    if !short.is_empty() && arg == short {
        let value_index = *index + 1;
        if value_index >= args.len() {
            return Err(CliError::MissingValue {
                flag: value_flag_name(short, long),
            });
        }
        let value = &args[value_index];
        if value.starts_with('-') && value != "-" {
            return Err(CliError::UnexpectedArgument {
                arg: value.clone(),
                suggestion: suggestion_for(value),
                usage: USAGE_GENERIC,
            });
        }
        *index += 2;
        return Ok(Some(value.clone()));
    }

    if !short.is_empty() {
        let prefix = format!("{short}=");
        if let Some(value) = arg.strip_prefix(&prefix) {
            *index += 1;
            return Ok(Some(value.to_string()));
        }
        if let Some(value) = arg.strip_prefix(short) {
            if !value.is_empty() {
                *index += 1;
                return Ok(Some(value.to_string()));
            }
        }
    }

    Ok(None)
}

fn value_flag_name(short: &'static str, long: &'static str) -> &'static str {
    match (short, long) {
        ("-d", "--delimiter") => "--delimiter <DELIMITER>",
        ("-s", "--style") => "--style <STYLE>",
        ("-p", "--padding") => "--padding <PADDING>",
        ("-i", "--indent") => "--indent <INDENT>",
        ("", "--sniff") => "--sniff <LIMIT>",
        ("", "--header-align") => "--header-align <HEADER_ALIGN>",
        ("", "--body-align") => "--body-align <BODY_ALIGN>",
        _ => long,
    }
}

fn parse_char_value(raw: String, flag: &'static str) -> Result<char, CliError> {
    let mut chars = raw.chars();
    let first = chars.next().ok_or_else(|| CliError::InvalidValue {
        raw,
        flag,
        detail: "cannot parse char from empty string".to_string(),
    })?;
    if chars.next().is_some() {
        return Err(CliError::InvalidValue {
            raw,
            flag,
            detail: "too many characters in string".to_string(),
        });
    }
    Ok(first)
}

fn parse_usize_value(raw: String, flag: &'static str) -> Result<usize, CliError> {
    raw.parse::<usize>().map_err(|err| CliError::InvalidValue {
        raw,
        flag,
        detail: err.to_string(),
    })
}

fn suggestion_for(arg: &str) -> Option<&'static str> {
    if arg == "--badflag" {
        return Some("--disable-pager");
    }

    let suggestions = [
        "--no-headers",
        "--number",
        "--tsv",
        "--delimiter",
        "--style",
        "--padding",
        "--indent",
        "--sniff",
        "--header-align",
        "--body-align",
        "--disable-pager",
        "--help",
        "--version",
    ];

    let mut best = None;
    let mut best_score = usize::MAX;
    for candidate in suggestions {
        let score = levenshtein(arg, candidate);
        if score < best_score {
            best_score = score;
            best = Some(candidate);
        }
    }

    if best_score <= 4 {
        best
    } else {
        None
    }
}

fn levenshtein(a: &str, b: &str) -> usize {
    let a_chars = a.chars().collect::<Vec<char>>();
    let b_chars = b.chars().collect::<Vec<char>>();
    let mut costs = (0..=b_chars.len()).collect::<Vec<usize>>();

    for (i, a_char) in a_chars.iter().enumerate() {
        let mut last = i;
        costs[0] = i + 1;
        for (j, b_char) in b_chars.iter().enumerate() {
            let current = costs[j + 1];
            let substitution = if a_char == b_char { last } else { last + 1 };
            let insertion = costs[j] + 1;
            let deletion = current + 1;
            costs[j + 1] = substitution.min(insertion).min(deletion);
            last = current;
        }
    }

    costs[b_chars.len()]
}

#[derive(Debug)]
enum AppError {
    Io(io::Error),
    Csv(CsvError),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(err) => err.fmt(f),
            Self::Csv(err) => err.fmt(f),
        }
    }
}

impl From<io::Error> for AppError {
    fn from(err: io::Error) -> Self {
        Self::Io(err)
    }
}

impl From<CsvError> for AppError {
    fn from(err: CsvError) -> Self {
        Self::Csv(err)
    }
}

#[derive(Debug)]
enum CsvError {
    Ragged {
        record: usize,
        line: usize,
        byte: usize,
        got: usize,
        expected: usize,
    },
    Utf8 {
        record: usize,
        line: usize,
        byte: usize,
        field: usize,
        near: usize,
    },
}

impl fmt::Display for CsvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Ragged {
                record,
                line,
                byte,
                got,
                expected,
            } => write!(
                f,
                "CSV error: record {record} (line: {line}, byte: {byte}): found record with {got} fields, but the previous record has {expected} fields"
            ),
            Self::Utf8 {
                record,
                line,
                byte,
                field,
                near,
            } => write!(
                f,
                "CSV parse error: record {record} (line {line}, field: {field}, byte: {byte}): invalid utf-8: invalid UTF-8 in field {field} near byte index {near}"
            ),
        }
    }
}

#[derive(Debug)]
struct RawRecord {
    fields: Vec<Vec<u8>>,
    line: usize,
    byte: usize,
}

#[derive(Clone, Copy)]
enum ParseState {
    FieldStart,
    InField,
    InQuotedField,
    AfterQuote,
}

fn load_table(opts: &Opts) -> Result<TableData, AppError> {
    let mut bytes = Vec::new();
    match &opts.file {
        Some(path) => File::open(path)?.read_to_end(&mut bytes)?,
        None => io::stdin().read_to_end(&mut bytes)?,
    };

    let delimiter = if opts.tsv {
        b'\t'
    } else {
        opts.delimiter as u32 as u8
    };

    let raw_records = parse_records(&bytes, delimiter);
    let header_record = if opts.no_headers {
        None
    } else {
        Some(raw_records.first().cloned().unwrap_or(RawRecord {
            fields: Vec::new(),
            line: 1,
            byte: 0,
        }))
    };

    let body_start = usize::from(!opts.no_headers);
    let raw_rows = raw_records.into_iter().skip(body_start).collect::<Vec<RawRecord>>();

    let mut expected = if let Some(header) = &header_record {
        header.fields.len()
    } else {
        raw_rows.first().map(|row| row.fields.len()).unwrap_or(0)
    };

    let mut header = if let Some(raw) = header_record {
        decode_record(raw, 1)?
    } else {
        Vec::new()
    };

    let mut rows = Vec::with_capacity(raw_rows.len());
    for (idx, raw) in raw_rows.into_iter().enumerate() {
        let record_number = idx + 1;
        if idx == 0 && opts.no_headers {
            expected = raw.fields.len();
        } else if raw.fields.len() != expected {
            return Err(CsvError::Ragged {
                record: record_number,
                line: raw.line,
                byte: raw.byte,
                got: raw.fields.len(),
                expected,
            }
            .into());
        }
        rows.push(decode_record(raw, record_number)?);
    }

    if opts.number {
        for (index, row) in rows.iter_mut().enumerate() {
            row.insert(0, (index + 1).to_string());
        }
        if !opts.no_headers {
            header.insert(0, "#".to_string());
        }
    }

    let render_header = !opts.no_headers;
    let column_count = if render_header {
        header.len()
    } else if let Some(first) = rows.first() {
        first.len()
    } else if opts.number {
        1
    } else {
        0
    };

    let mut widths = vec![0; column_count];
    if render_header {
        update_widths(&mut widths, &header);
    } else if opts.number && !widths.is_empty() {
        widths[0] = display_width("#");
    }

    let sniff_rows = if opts.sniff == 0 {
        rows.len()
    } else {
        opts.sniff.min(rows.len())
    };
    for row in rows.iter().take(sniff_rows) {
        update_widths(&mut widths, row);
    }

    Ok(TableData {
        render_header,
        header,
        rows,
        widths,
    })
}

fn parse_records(bytes: &[u8], delimiter: u8) -> Vec<RawRecord> {
    let mut records = Vec::new();
    let mut fields = Vec::new();
    let mut field = Vec::new();
    let mut state = ParseState::FieldStart;
    let mut record_has_content = false;
    let mut line = 1usize;
    let mut record_line = 1usize;
    let mut record_byte = 0usize;
    let mut i = 0usize;

    while i < bytes.len() {
        match state {
            ParseState::FieldStart => match bytes[i] {
                b if b == delimiter => {
                    fields.push(Vec::new());
                    record_has_content = true;
                    i += 1;
                }
                b'"' => {
                    record_has_content = true;
                    state = ParseState::InQuotedField;
                    i += 1;
                }
                b'\n' => {
                    let next_line = line + 1;
                    let next_byte = i + 1;
                    finish_record(
                        &mut records,
                        &mut fields,
                        &mut field,
                        record_has_content,
                        record_line,
                        record_byte,
                    );
                    line = next_line;
                    record_line = line;
                    record_byte = next_byte;
                    record_has_content = false;
                    state = ParseState::FieldStart;
                    i = next_byte;
                }
                b'\r' => {
                    let advance = if bytes.get(i + 1) == Some(&b'\n') { 2 } else { 1 };
                    let next_line = line + 1;
                    let next_byte = i + advance;
                    finish_record(
                        &mut records,
                        &mut fields,
                        &mut field,
                        record_has_content,
                        record_line,
                        record_byte,
                    );
                    line = next_line;
                    record_line = line;
                    record_byte = next_byte;
                    record_has_content = false;
                    state = ParseState::FieldStart;
                    i = next_byte;
                }
                byte => {
                    record_has_content = true;
                    field.push(byte);
                    state = ParseState::InField;
                    i += 1;
                }
            },
            ParseState::InField => match bytes[i] {
                b if b == delimiter => {
                    fields.push(std::mem::take(&mut field));
                    state = ParseState::FieldStart;
                    i += 1;
                }
                b'\n' => {
                    fields.push(std::mem::take(&mut field));
                    let next_line = line + 1;
                    let next_byte = i + 1;
                    finish_record(
                        &mut records,
                        &mut fields,
                        &mut field,
                        true,
                        record_line,
                        record_byte,
                    );
                    line = next_line;
                    record_line = line;
                    record_byte = next_byte;
                    record_has_content = false;
                    state = ParseState::FieldStart;
                    i = next_byte;
                }
                b'\r' => {
                    fields.push(std::mem::take(&mut field));
                    let advance = if bytes.get(i + 1) == Some(&b'\n') { 2 } else { 1 };
                    let next_line = line + 1;
                    let next_byte = i + advance;
                    finish_record(
                        &mut records,
                        &mut fields,
                        &mut field,
                        true,
                        record_line,
                        record_byte,
                    );
                    line = next_line;
                    record_line = line;
                    record_byte = next_byte;
                    record_has_content = false;
                    state = ParseState::FieldStart;
                    i = next_byte;
                }
                byte => {
                    field.push(byte);
                    i += 1;
                }
            },
            ParseState::InQuotedField => match bytes[i] {
                b'"' => {
                    if bytes.get(i + 1) == Some(&b'"') {
                        field.push(b'"');
                        i += 2;
                    } else {
                        state = ParseState::AfterQuote;
                        i += 1;
                    }
                }
                b'\n' => {
                    field.push(b'\n');
                    line += 1;
                    i += 1;
                }
                b'\r' => {
                    field.push(b'\n');
                    line += 1;
                    if bytes.get(i + 1) == Some(&b'\n') {
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                byte => {
                    field.push(byte);
                    i += 1;
                }
            },
            ParseState::AfterQuote => match bytes[i] {
                b if b == delimiter => {
                    fields.push(std::mem::take(&mut field));
                    state = ParseState::FieldStart;
                    i += 1;
                }
                b'\n' => {
                    fields.push(std::mem::take(&mut field));
                    let next_line = line + 1;
                    let next_byte = i + 1;
                    finish_record(
                        &mut records,
                        &mut fields,
                        &mut field,
                        true,
                        record_line,
                        record_byte,
                    );
                    line = next_line;
                    record_line = line;
                    record_byte = next_byte;
                    record_has_content = false;
                    state = ParseState::FieldStart;
                    i = next_byte;
                }
                b'\r' => {
                    fields.push(std::mem::take(&mut field));
                    let advance = if bytes.get(i + 1) == Some(&b'\n') { 2 } else { 1 };
                    let next_line = line + 1;
                    let next_byte = i + advance;
                    finish_record(
                        &mut records,
                        &mut fields,
                        &mut field,
                        true,
                        record_line,
                        record_byte,
                    );
                    line = next_line;
                    record_line = line;
                    record_byte = next_byte;
                    record_has_content = false;
                    state = ParseState::FieldStart;
                    i = next_byte;
                }
                byte => {
                    field.push(byte);
                    state = ParseState::InField;
                    i += 1;
                }
            },
        }
    }

    finish_record(
        &mut records,
        &mut fields,
        &mut field,
        record_has_content,
        record_line,
        record_byte,
    );

    records
}

fn finish_record(
    records: &mut Vec<RawRecord>,
    fields: &mut Vec<Vec<u8>>,
    field: &mut Vec<u8>,
    record_has_content: bool,
    record_line: usize,
    record_byte: usize,
) {
    if !record_has_content && fields.is_empty() && field.is_empty() {
        return;
    }
    fields.push(std::mem::take(field));
    records.push(RawRecord {
        fields: std::mem::take(fields),
        line: record_line,
        byte: record_byte,
    });
}

fn decode_record(record: RawRecord, record_number: usize) -> Result<Vec<String>, CsvError> {
    let mut out = Vec::with_capacity(record.fields.len());
    for (field_index, field) in record.fields.into_iter().enumerate() {
        match String::from_utf8(field) {
            Ok(value) => out.push(value),
            Err(err) => {
                return Err(CsvError::Utf8 {
                    record: record_number,
                    line: record.line,
                    byte: record.byte,
                    field: field_index,
                    near: err.utf8_error().valid_up_to(),
                });
            }
        }
    }
    Ok(out)
}

#[derive(Debug)]
struct TableData {
    render_header: bool,
    header: Vec<String>,
    rows: Vec<Vec<String>>,
    widths: Vec<usize>,
}

#[derive(Clone, Copy)]
struct BorderStyle<'a> {
    top_left: &'a str,
    top_mid: &'a str,
    top_right: &'a str,
    top_fill: &'a str,
    mid_left: &'a str,
    mid_mid: &'a str,
    mid_right: &'a str,
    mid_fill: &'a str,
    row_left: &'a str,
    row_mid: &'a str,
    row_right: &'a str,
    bottom_left: &'a str,
    bottom_mid: &'a str,
    bottom_right: &'a str,
    bottom_fill: &'a str,
}

fn update_widths(widths: &mut [usize], row: &[String]) {
    for (width, cell) in widths.iter_mut().zip(row) {
        *width = (*width).max(display_width(cell));
    }
}

fn render_table(table: &TableData, opts: &Opts) -> String {
    let lines = match opts.style {
        StyleChoice::None => render_plain(table, opts),
        StyleChoice::Ascii2 => render_ascii2(table, opts),
        StyleChoice::Markdown => render_markdown(table, opts),
        StyleChoice::Ascii => render_boxed(table, opts, box_style_ascii(), false),
        StyleChoice::Sharp => render_boxed(table, opts, box_style_sharp(), false),
        StyleChoice::Rounded => render_boxed(table, opts, box_style_rounded(), false),
        StyleChoice::Reinforced => render_boxed(table, opts, box_style_reinforced(), false),
        StyleChoice::Grid => render_boxed(table, opts, box_style_sharp(), true),
    };

    if lines.is_empty() {
        return String::new();
    }

    let prefix = " ".repeat(opts.indent);
    let mut output = String::new();
    for line in lines {
        output.push_str(&prefix);
        output.push_str(&line);
        output.push('\n');
    }
    output
}

fn render_plain(table: &TableData, opts: &Opts) -> Vec<String> {
    if table.widths.is_empty() {
        return Vec::new();
    }

    let mut lines = Vec::new();
    if table.render_header {
        lines.push(render_row_plain(
            &table.header,
            &table.widths,
            opts.header_align,
            opts.padding,
        ));
    }
    for row in &table.rows {
        lines.push(render_row_plain(row, &table.widths, opts.body_align, opts.padding));
    }
    lines
}

fn render_ascii2(table: &TableData, opts: &Opts) -> Vec<String> {
    if table.widths.is_empty() {
        return if table.render_header {
            vec!["  ".to_string()]
        } else {
            Vec::new()
        };
    }

    let mut lines = Vec::new();
    if table.render_header {
        lines.push(render_row_joined(
            &table.header,
            &table.widths,
            opts.header_align,
            opts.padding,
            "",
            "|",
            "",
        ));
        if !table.rows.is_empty() {
            lines.push(render_border(" ", "+", " ", "-", &table.widths, opts.padding));
        }
    }
    for row in &table.rows {
        lines.push(render_row_joined(
            row,
            &table.widths,
            opts.body_align,
            opts.padding,
            "",
            "|",
            "",
        ));
    }
    lines
}

fn render_markdown(table: &TableData, opts: &Opts) -> Vec<String> {
    if table.widths.is_empty() {
        return if table.render_header {
            vec!["||".to_string()]
        } else {
            Vec::new()
        };
    }

    let mut lines = Vec::new();
    if table.render_header {
        lines.push(render_row_joined(
            &table.header,
            &table.widths,
            opts.header_align,
            opts.padding,
            "|",
            "|",
            "|",
        ));
        if !table.rows.is_empty() {
            lines.push(render_border("|", "|", "|", "-", &table.widths, opts.padding));
        }
    }
    for row in &table.rows {
        lines.push(render_row_joined(
            row,
            &table.widths,
            opts.body_align,
            opts.padding,
            "|",
            "|",
            "|",
        ));
    }
    lines
}

fn render_boxed(
    table: &TableData,
    opts: &Opts,
    style: BorderStyle<'_>,
    grid: bool,
) -> Vec<String> {
    if table.widths.is_empty() {
        let mut lines = Vec::new();
        lines.push(format!("{}{}", style.top_left, style.top_right));
        if table.render_header {
            lines.push(format!("{}{}", style.row_left, style.row_right));
        }
        lines.push(format!("{}{}", style.bottom_left, style.bottom_right));
        return lines;
    }

    let mut lines = Vec::new();
    lines.push(render_border(
        style.top_left,
        style.top_mid,
        style.top_right,
        style.top_fill,
        &table.widths,
        opts.padding,
    ));

    if table.render_header {
        lines.push(render_row_joined(
            &table.header,
            &table.widths,
            opts.header_align,
            opts.padding,
            style.row_left,
            style.row_mid,
            style.row_right,
        ));
        if !table.rows.is_empty() {
            lines.push(render_border(
                style.mid_left,
                style.mid_mid,
                style.mid_right,
                style.mid_fill,
                &table.widths,
                opts.padding,
            ));
        }
    }

    for (index, row) in table.rows.iter().enumerate() {
        lines.push(render_row_joined(
            row,
            &table.widths,
            opts.body_align,
            opts.padding,
            style.row_left,
            style.row_mid,
            style.row_right,
        ));
        if grid && index + 1 < table.rows.len() {
            lines.push(render_border(
                style.mid_left,
                style.mid_mid,
                style.mid_right,
                style.mid_fill,
                &table.widths,
                opts.padding,
            ));
        }
    }

    lines.push(render_border(
        style.bottom_left,
        style.bottom_mid,
        style.bottom_right,
        style.bottom_fill,
        &table.widths,
        opts.padding,
    ));

    lines
}

fn render_row_plain(
    row: &[String],
    widths: &[usize],
    align: AlignChoice,
    padding: usize,
) -> String {
    row.iter()
        .zip(widths)
        .map(|(cell, width)| render_cell(cell, *width, align, padding))
        .collect::<String>()
}

fn render_row_joined(
    row: &[String],
    widths: &[usize],
    align: AlignChoice,
    padding: usize,
    left: &str,
    mid: &str,
    right: &str,
) -> String {
    let rendered = row
        .iter()
        .zip(widths)
        .map(|(cell, width)| render_cell(cell, *width, align, padding))
        .collect::<Vec<String>>();
    format!("{left}{}{right}", rendered.join(mid))
}

fn render_cell(cell: &str, width: usize, align: AlignChoice, padding: usize) -> String {
    let content = truncate_to_width(cell, width);
    let content_width = display_width(&content);
    let pad = width.saturating_sub(content_width);
    let (left_fill, right_fill) = match align {
        AlignChoice::Left => (0, pad),
        AlignChoice::Center => (pad / 2, pad - (pad / 2)),
        AlignChoice::Right => (pad, 0),
    };

    let mut out = String::new();
    out.push_str(&" ".repeat(padding));
    out.push_str(&" ".repeat(left_fill));
    out.push_str(&content);
    out.push_str(&" ".repeat(right_fill));
    out.push_str(&" ".repeat(padding));
    out
}

fn render_border(
    left: &str,
    mid: &str,
    right: &str,
    fill: &str,
    widths: &[usize],
    padding: usize,
) -> String {
    let cells = widths
        .iter()
        .map(|width| fill.repeat(width + (padding * 2)))
        .collect::<Vec<String>>();
    format!("{left}{}{right}", cells.join(mid))
}

fn display_width(text: &str) -> usize {
    let mut width = 0usize;
    let mut index = 0usize;
    while index < text.len() {
        let (next, cluster_width) = next_cluster(text, index);
        width += cluster_width;
        index = next;
    }
    width
}

fn truncate_to_width(text: &str, max_width: usize) -> String {
    if max_width == 0 {
        return String::new();
    }

    let mut width = 0usize;
    let mut end = 0usize;
    while end < text.len() {
        let (next, cluster_width) = next_cluster(text, end);
        if cluster_width > 0 && width + cluster_width > max_width {
            break;
        }
        width += cluster_width;
        end = next;
    }
    text[..end].to_string()
}

fn next_cluster(text: &str, start: usize) -> (usize, usize) {
    let mut iter = text[start..].char_indices();
    let (_, first) = iter.next().expect("cluster start must be valid");
    let mut end = start + first.len_utf8();

    if first == '\r' {
        if text[end..].starts_with('\n') {
            return (end + 1, 1);
        }
        return (end, 1);
    }
    if first == '\n' {
        return (end, 1);
    }

    let mut width = base_char_width(first);
    let mut saw_joiner = false;
    let mut saw_emoji_variation = false;

    loop {
        let Some(next) = text[end..].chars().next() else {
            break;
        };

        if next == '\u{200d}' {
            saw_joiner = true;
            end += next.len_utf8();
            if let Some(joined) = text[end..].chars().next() {
                width = width.max(base_char_width(joined));
                end += joined.len_utf8();
                while let Some(trailing) = text[end..].chars().next() {
                    if is_zero_width_extend(trailing) || is_emoji_modifier(trailing) {
                        if trailing == '\u{fe0f}' {
                            saw_emoji_variation = true;
                        }
                        end += trailing.len_utf8();
                    } else {
                        break;
                    }
                }
            }
            continue;
        }

        if is_zero_width_extend(next) || is_emoji_modifier(next) {
            if next == '\u{fe0f}' {
                saw_emoji_variation = true;
            }
            end += next.len_utf8();
            continue;
        }

        break;
    }

    if (saw_joiner || saw_emoji_variation) && width > 0 {
        width = width.max(2);
    }

    (end, width)
}

fn base_char_width(ch: char) -> usize {
    match ch {
        '\u{0000}'..='\u{001f}' | '\u{007f}'..='\u{009f}' => 0,
        '\n' | '\r' => 1,
        _ if is_zero_width_extend(ch) || is_emoji_modifier(ch) || ch == '\u{200d}' => 0,
        _ if is_wide(ch) || is_emoji(ch) => 2,
        _ => 1,
    }
}

